def ph(cap, body, note=''):
    n=f'<div class="mut" style="color:#06B6D4;font-weight:700">{note}</div>' if note else ''
    return f'<div class="col"><div class="cap">{cap}</div>{n}<div class="ph"><div class="b b1"></div><div class="b b2"></div><div class="b b3"></div><div class="b b4"></div><div class="z">{body}</div></div></div>'
def sec(c1,c2,i,t,d,soon=True):
    badge='<span class="pill" style="background:#ffffff1c">قريباً</span>' if soon else '<span class="pill" style="background:#22c55e44;color:#7CFF9B">يعمل</span>'
    return f'<div class="card glass" style="{"opacity:.78" if soon else "border-color:#38EF7D99"}"><div class="ic" style="background:linear-gradient(135deg,{c1},{c2})">{ic(i,24)}</div><div style="flex:1"><b style="font-size:15px">{t}</b><div class="mut">{d}</div></div>{badge}</div>'
def lang(c1,c2,txt,t,d,col='#fff'):
    return f'<div class="card glass"><div class="ic" style="background:linear-gradient(135deg,{c1},{c2});color:{col};font-weight:900;font-size:16px">{txt}</div><div style="flex:1"><b style="font-size:16px">{t}</b><div class="mut">{d}</div></div>{ic("back",20)}</div>'
